// Cross-repo contract compatibility test — grave-indexer (producer) ↔
// graveyield-console (consumer), ConsoleSnapshot schemaVersion 2.
//
// WHAT THIS PINS
//   The committed fixture (src/lib/gy/snapshot.json) is generated by the
//   grave-indexer PRODUCTION serializer — buildConsoleSnapshot(), the same
//   function `grave-indexer console-snapshot` (src/cli.ts) calls to emit
//   console-snapshot.json artifacts. See
//   src/lib/gy/snapshot-fixture/PROVENANCE.md for the pinned
//   producer commit, the digest, and the honest synthetic-data disclosure.
//   These tests prove that a REAL producer artifact:
//     - passes the console's fail-closed parser (the same gate used by the
//       server transport and the client hydration path),
//     - flows through the console's normal consumption path unchanged
//       (pool mapping, criteria rows, freshness, transport envelope),
//     - preserves pool identity, counts, failures and the D-01 M1-sourcing
//       fields exactly as produced,
//   and that a v1 producer artifact is rejected, never reinterpreted.
//
// CONTRACT-SHARING MECHANISM (honest statement)
//   There is NO shared npm package, JSON Schema file, or generated-types
//   artifact between the two repositories. The contract is held together
//   by: (1) the indexer's normative reader src/consoleSnapshotParse.ts,
//   (2) this repo's mirror parser in snapshotContract.ts, (3) the
//   serializer-generated fixture + sha256 digest pin verified below, and
//   (4) the documented regeneration procedure in PROVENANCE.md. Any schema
//   change must bump schemaVersion and update all four legs — the digest
//   pin below fails if the committed fixture drifts without a deliberate
//   regeneration, and the mirror's negative battery fails if the consumer
//   drifts from the pinned rules.

/// <reference types="bun-types" />
import { describe, test, expect } from "bun:test";
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { resolve } from "node:path";

import {
  parseSnapshot,
  snapshotFreshness,
  snapshotPools,
  snapshotCriteriaOf,
  poolFromSnapshot,
  SnapshotError,
  CANONICAL_WSOL_MINT,
  type ConsoleSnapshot,
} from "../snapshotContract";
import { bytesToPayload } from "../snapshotSource";
import { hydrateTransportPayload, effectiveTransportState } from "../snapshotTransport";

const REPO_ROOT = resolve(import.meta.dir, "../../../..");
const FIXTURE_PATH = resolve(REPO_ROOT, "src/lib/gy/snapshot.json");
const PROVENANCE_PATH = resolve(REPO_ROOT, "src/lib/gy/snapshot-fixture/PROVENANCE.md");

const FIXTURE_BYTES = readFileSync(FIXTURE_PATH);
const FIXTURE_JSON: unknown = JSON.parse(new TextDecoder("utf-8").decode(FIXTURE_BYTES));
const FIXTURE_SHA256 = createHash("sha256").update(FIXTURE_BYTES).digest("hex");

/** The fixture's own generation clock (fresh for consumption-path tests). */
const GENERATED_AT = (FIXTURE_JSON as { generatedAtUnixMs: number }).generatedAtUnixMs;
const NOW = GENERATED_AT + 60_000;

describe("snapshotV2Compat — the committed fixture is the pinned producer artifact", () => {
  test("sha256 matches the digest pinned in PROVENANCE.md — drift fails loudly", () => {
    const provenance = readFileSync(PROVENANCE_PATH, "utf-8");
    const pinned = provenance.match(/sha256\(snapshot\.json\) = ([0-9a-f]{64})/);
    expect(pinned).not.toBeNull();
    expect(FIXTURE_SHA256).toBe(pinned![1]!);
  });

  test("the fixture is a schemaVersion 2 artifact (never a hand-built v1)", () => {
    const snap = parseSnapshot(FIXTURE_JSON);
    expect(snap.schemaVersion).toBe(2);
  });
});

describe("snapshotV2Compat — real producer output through the console consumption path", () => {
  const snap: ConsoleSnapshot = parseSnapshot(FIXTURE_JSON);

  test("the console parser accepts the real artifact and reads the sourcing fields", () => {
    for (const p of snap.pools) {
      expect(p.coinMint).not.toBe(CANONICAL_WSOL_MINT); // coin_mint side is the memecoin
      expect(p.pcMint).toBe(CANONICAL_WSOL_MINT); // pc_mint side is WSOL (D-01)
      expect(p.m1Sourcing).toEqual({ eligible: true, wsolSide: "pc_mint", reason: null });
      expect(p.wsolSide.coinIsWsol).toBe(false);
      expect(p.wsolSide.memecoinMint).toBe(p.coinMint);
    }
  });

  test("pool identity, counts, failures and thresholds survive the boundary unchanged", () => {
    const raw = FIXTURE_JSON as {
      pools: { address: string; fingerprint: string; wsolReserveLamports: string }[];
      counts: Record<string, number>;
      failures: { stage: string }[];
      thresholds: Record<string, string>;
    };
    expect(snap.pools.map((p) => p.address)).toEqual(raw.pools.map((p) => p.address));
    expect(snap.pools.map((p) => p.fingerprint)).toEqual(raw.pools.map((p) => p.fingerprint));
    expect(snap.counts).toEqual(raw.counts as typeof snap.counts);
    expect(snap.counts.enriched).toBe(snap.pools.length);
    expect(snap.counts.m1SourcingRejected).toBe(snap.failures.filter((f) => f.stage === "m1-sourcing").length);
    expect(snap.failures.map((f) => f.stage)).toEqual(raw.failures.map((f) => f.stage));
    expect(snap.thresholds).toEqual(raw.thresholds as typeof snap.thresholds);
  });

  test("pools map through the console's normal consumption path with honest states", () => {
    const pools = snapshotPools(snap);
    expect(pools.length).toBe(snap.pools.length);
    for (let i = 0; i < pools.length; i++) {
      expect(pools[i]!.address).toBe(snap.pools[i]!.address);
      expect(pools[i]!.state).toBe("discovered");
      expect(pools[i]!.score).toBe(0); // never fabricated
      expect(pools[i]!.quoteSymbol).toBe("WSOL");
      expect(pools[i]!.quoteReserveLamports).toBe(BigInt(snap.pools[i]!.wsolReserveLamports));
      expect(pools[i]!.snapshotFingerprint).toBe(snap.pools[i]!.fingerprint);
    }
    // Pool B (last swap not derivable) is "unavailable", never rendered as zero.
    const withoutSwap = snap.pools.find((p) => p.lastSwap === null);
    if (withoutSwap) {
      const mapped = poolFromSnapshot(withoutSwap, snap);
      expect(mapped.lastSwapUnix).toBe(0);
      expect(mapped.note).toContain("unavailable");
    }
    // Criteria rows read the serializer's honest C1/C3 states; C2/C4/C5/C6 pending.
    const rows = snapshotCriteriaOf(pools[0]!, NOW, snap);
    expect(rows.find((r) => r.id === "C1")!.state).toBe(snap.pools[0]!.criteria.c1Inactivity);
    expect(rows.find((r) => r.id === "C3")!.state).toBe(snap.pools[0]!.criteria.c3MinTvl);
    for (const id of ["C2", "C4", "C5", "C6"]) {
      expect(rows.find((r) => r.id === id)!.state).toBe("pending");
    }
    // Freshness math on the real artifact.
    expect(snapshotFreshness(snap, GENERATED_AT + 86_400_000)).toBe("fresh");
    expect(snapshotFreshness(snap, GENERATED_AT + 86_400_000 + 1)).toBe("stale");
  });

  test("the real artifact rides the server transport gate (bytesToPayload) as valid/real", () => {
    const payload = bytesToPayload(FIXTURE_BYTES, {
      nowMs: NOW,
      checkedAtUnixMs: NOW,
      source: { kind: "path", uri: "/mnt/gy/console-snapshot.json" },
    });
    expect(payload.artifactState).toBe("valid");
    expect(payload.dataState).toBe("real");
    expect(payload.reasonCode).toBeNull();
    expect(payload.snapshot).not.toBeNull();
    expect(payload.snapshot!.pools.length).toBe(snap.pools.length);
  });

  test("the real artifact rides the client hydration gate (hydrateTransportPayload)", () => {
    const server = bytesToPayload(FIXTURE_BYTES, {
      nowMs: NOW,
      checkedAtUnixMs: NOW,
      source: { kind: "path", uri: "/mnt/gy/console-snapshot.json" },
    });
    const hydrated = hydrateTransportPayload(JSON.parse(JSON.stringify(server)), NOW);
    expect(hydrated).not.toBeNull();
    expect(hydrated!.artifactState).toBe("valid");
    expect(hydrated!.snapshot!.pools.length).toBe(snap.pools.length);
    expect(hydrated!.snapshot!.counts.m1SourcingRejected).toBe(snap.counts.m1SourcingRejected);
    // Display-time freshness degrades honestly when the budget lapses.
    const aged = effectiveTransportState(hydrated!, GENERATED_AT + 86_400_000 + 1);
    expect(aged.artifactState).toBe("stale");
    expect(aged.dataState).toBe("stale");
  });

  test("a v1 producer artifact is rejected by the consumer — never reinterpreted as v2", () => {
    const raw = JSON.parse(JSON.stringify(FIXTURE_JSON)) as Record<string, unknown>;
    for (const p of raw.pools as Record<string, unknown>[]) {
      delete p.coinMint;
      delete p.pcMint;
      delete p.m1Sourcing;
    }
    delete (raw.counts as Record<string, unknown>).m1SourcingRejected;
    raw.schemaVersion = 1;
    expect(() => parseSnapshot(raw)).toThrow(SnapshotError);
  });
});
